// Builds hooks/colors.ts, the theme's colors, from the palette below.
//
// The design system's token names are generated by `make-colors.js`, which ships inside Claude Code's built-in
// `plugin-authoring` skill and is not part of this repository. Pass its path:
//
//   node plugins/vp-cc-theme-hammerhead/scripts/build-colors.mjs <path to make-colors.js>
//
// Run `/plugin-authoring` in a session to have Claude Code write the skill's files and name the folder.
// The script refuses a palette that the Desktop app would not paint.

import { writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const source = process.argv[2]
if (source === undefined) {
  console.error('Usage: node build-colors.mjs <path to make-colors.js>')
  process.exit(1)
}
const { makeColors } = await import(pathToFileURL(resolve(source)).href)

// Dark mode: Gruvbox (morhetz), bright accents. Light mode: Everforest light (sainnhe), medium background.
const PALETTE = {
  label: 'Hammerhead: Gruvbox dark, Everforest light',
  id: 'vp-cc-theme-hammerhead',
  codeTheme: { light: 'everforest-light', dark: 'gruvbox-dark-medium' },
  light: {
    gray: {
      anchors: {
        'surface-0': '#efebd4',
        'surface-1': '#f4f0d9',
        'surface-2': '#fdf6e3',
        'text-primary': '#3d484d',
        'text-secondary': '#4f5b62',
        'text-muted': '#6c7a72',
      },
    },
    roles: { accent: '#35a77c', danger: '#f85552', success: '#8da101', warning: '#dfa000', pro: '#df69ba' },
    git: { added: '#8da101', removed: '#f85552', modified: '#3a94c5', merged: '#df69ba' },
  },
  dark: {
    gray: {
      anchors: {
        'surface-0': '#1d2021',
        'surface-1': '#232425',
        'surface-2': '#282828',
        'surface-3': '#2a2928',
        'text-primary': '#fbf1c7',
        'text-secondary': '#d5c4a1',
        'text-muted': '#a89984',
      },
    },
    roles: { accent: '#fe8019', danger: '#fb4934', success: '#b8bb26', warning: '#fabd2f', pro: '#d3869b' },
    git: { added: '#b8bb26', removed: '#fb4934', modified: '#83a598', merged: '#d3869b' },
  },
}

const { theme, problems } = makeColors(PALETTE)
const unpainted = problems.filter(line => line.startsWith("Desktop won't paint"))
if (unpainted.length > 0) {
  console.error(unpainted.join('\n'))
  process.exit(1)
}

const target = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'colors.ts')
writeFileSync(
  target,
  `// Generated by scripts/build-colors.mjs from its palette. Do not edit by hand: change the palette and run it again.
import type { ThemeColors } from 'claude-code'

export const COLORS: ThemeColors = ${JSON.stringify(theme, null, 2)}
`,
)
console.log(`Wrote ${target} (${problems.length} contrast notes below the design system's bar, none that stop painting)`)
